parameters.text:
=Analyze this software incident.

Title: {{ $json.title }}
Description: {{ $json.description }}
Service: {{ $json.service }}

Return ONLY compact valid JSON:

{
  "severity": "low|medium|high|critical",
  "category": "short category",
  "team": "Backend|Frontend|DevOps|Security|Data|Platform|Payments|General Engineering",
  "summary": "short sentence",
  "probable_cause": "short hypothesis",
  "recommended_action": "short action"
}

No markdown. No explanation. Keep every value concise.

parameters.jsCode:
const base = $('Normalize Incident').first().json;

let raw = $json.text ?? $json.output ?? $json;
let triage = {};

if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
  triage = raw;
} else if (typeof raw === 'string') {
  const cleaned = raw
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const jsonCandidate = cleaned.match(/\{[\s\S]*\}/)?.[0] ?? cleaned;

  try {
    triage = JSON.parse(jsonCandidate);
  } catch {
    triage = {};
  }
}

const allowedSeverities = new Set(['low', 'medium', 'high', 'critical']);
const requestedSeverity = String(triage.severity || '').trim().toLowerCase();
const severity = allowedSeverities.has(requestedSeverity) ? requestedSeverity : 'medium';

const allowedTeams = new Set([
  'Backend',
  'Frontend',
  'DevOps',
  'Security',
  'Data',
  'Platform',
  'Payments',
  'General Engineering'
]);

const requestedTeam = String(triage.team || '').trim();
const team = allowedTeams.has(requestedTeam) ? requestedTeam : 'General Engineering';

const category = String(triage.category || 'unknown').trim() || 'unknown';

const slaMinutes = {
  critical: 15,
  high: 30,
  medium: 120,
  low: 240
};

const normalizedService = String(base.service || 'unknown-service')
  .trim()
  .toLowerCase()
  .replace(/\s+/g, '-');

const normalizedTitle = String(base.title || 'untitled incident')
  .trim()
  .toLowerCase()
  .replace(/\s+/g, ' ');

return [{
  json: {
    ...base,
    severity,
    category,
    team,
    ai_summary: String(triage.summary || base.description || base.title).trim(),
    probable_cause: String(triage.probable_cause || 'Unknown — requires investigation').trim(),
    recommended_action: String(triage.recommended_action || 'Review logs and investigate the affected service').trim(),
    fingerprint: `${normalizedService}|${normalizedTitle}`,
    status: 'investigating',
    sla_minutes: slaMinutes[severity] || 120,
    sla_wait_seconds: base.demo_mode
      ? 20
      : (slaMinutes[severity] || 120) * 60,
    triage_parse_fallback: Object.keys(triage).length === 0
  }
}];

const current = $('Prepare Incident').first().json;

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id != null)
  .sort((a, b) => {
    const ta = new Date(a.last_seen_at || a.updated_at || a.created_at || 0).getTime();
    const tb = new Date(b.last_seen_at || b.updated_at || b.created_at || 0).getTime();
    return tb - ta;
  });

const existing = rows.find(r =>
  r.fingerprint === current.fingerprint &&
  !['resolved', 'closed'].includes(String(r.status || '').toLowerCase())
);

return [{
  json: {
    ...current,
    duplicate: Boolean(existing),
    existing_incident_id: existing?.id ?? null,
    existing_issue_number: existing?.github_issue_number ?? null,
    existing_issue_url: existing?.github_issue_url ?? '',
    existing_status: existing?.status ?? null,
    duplicate_count: existing ? Number(existing.duplicate_count || 1) + 1 : 1
  }
}];

