parameters.jsCode:
const incident = $('Prepare Incident').first().json;
const url = String(incident.service_url || '').trim();
const validUrl = /^https?:\/\//i.test(url);
const input = $input.first()?.json ?? {};

let health_check;

if (!validUrl) {
  health_check = {
    checked: false,
    url,
    reason: url ? 'Invalid service_url; only http/https URLs are checked' : 'No service_url supplied'
  };
} else if (input.error) {
  health_check = {
    checked: true,
    url,
    reachable: false,
    healthy: false,
    error: String(input.error.message || input.error.description || 'Health check request failed')
  };
} else {
  const statusCodeRaw = input.statusCode ?? input.status ?? null;
  const statusCode = statusCodeRaw === null ? null : Number(statusCodeRaw);

  let body = input.body ?? '';
  if (typeof body !== 'string') {
    try {
      body = JSON.stringify(body);
    } catch {
      body = String(body);
    }
  }

  health_check = {
    checked: true,
    url,
    reachable: true,
    status_code: Number.isFinite(statusCode) ? statusCode : null,
    healthy: Number.isFinite(statusCode) ? statusCode >= 200 && statusCode < 400 : null,
    response_preview: body.slice(0, 500)
  };
}

return [{
  json: {
    ...incident,
    health_check
  }
}];
